import logging

from taf.internal.execution.base import Executor
from .local_pty_process_factory import LocalPtyProcessFactory
from .local_process_factory import LocalProcessFactory

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class LocalExecutor(Executor):
    """
    Executor interface for subprocess.
    """

    def __init__(self, **kwargs):
        super(LocalExecutor, self).__init__(**kwargs)
        self._process_factories = {}
        for use_tty in (True, False):
            self._process_factories[use_tty] = self._create_process_factory(use_tty=use_tty)

    def raw_execute(self, command, use_tty=False):
        """
         Execute a command and wait until it finishes.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: stdout, stderr, exit status
        :rtype: bytes, bytes, int
         """
        logger.debug("executing {command!r} on local host {with_tty} terminal".format(
            command=command,
            with_tty="with" if use_tty else "without"))
        stdout, stderr, exit_status = self._raw_execute(command, use_tty=use_tty)
        logger.debug("stdout={stdout!r}, stderr={stderr!r}, exit_status={exit_status!r}".format(
            stdout=stdout,
            stderr=stderr,
            exit_status=exit_status))
        return stdout, stderr, exit_status

    def start(self, command, use_tty=False):
        """
        Start a command.

        Adds logging to start of command.

        :param str command: command to be executed
        :param bool use_tty: if True, use a terminal when executing the command

        :return: process
        :rtype: Process
        """
        logger.debug("starting {command!r} on local host {with_tty} terminal".format(
            command=command,
            with_tty="with" if use_tty else "without"))
        return self._start(command, use_tty=use_tty)

    def _start(self, command, use_tty=False):
        """
        Start a command.

        :param str command: command to be executed

        :return: process
        :rtype: Process
        """
        return self._process_factories[use_tty].create_process(command)

    def _create_local_pty_process_factory(self):
        return LocalPtyProcessFactory()

    def _create_local_process_factory(self):
        return LocalProcessFactory()

    def _create_process_factory(self, use_tty):
        if use_tty:
            return self._create_local_pty_process_factory()
        else:
            return self._create_local_process_factory()
